(function(){'use strict';
const $=id=>document.getElementById(id),R=AvalonRoads,B=window.DesktopApp?.avalon,esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const panel=document.createElement('section');panel.className='panel avalon-roads';panel.innerHTML=`<h2>Граф переходов и маршруты</h2><p class="hint">Сохраняются только ваши наблюдения. Обводка показывает тир; цвет квадрата — тип внешней зоны, подпись внутри — её тир и качество; путь через Авалон всё равно проходит по землям с полным лутом.</p>
<div id="avalon-engine-controls"><div class="avalon-actions"><button class="button" id="roads-engine-import">Подключить движок Checker</button><button class="button" id="roads-engine-choose">Выбрать другую папку…</button><button class="button" id="roads-record">Начать запись переходов</button><button class="button" id="roads-stop">Остановить запись</button><button class="button" id="roads-engine-scan">Считать портал через 3 секунды</button></div><p id="roads-engine" class="hint" role="status"></p><p id="roads-status" role="status" class="hint"></p><div id="roads-engine-settings"></div></div>
<details><summary>Как сканировать порталы</summary><p>Один раз подключите движок из скачанной папки Checker. Библиотеки будут скопированы в Albion Lab; отдельная программа, её окно и группа Roads не нужны. Настройте область названия текущей зоны, выберите сервер и начните запись.</p><p>В игре наведите курсор на подсказку портала и нажмите Ctrl+Shift+P или выбранную кнопку мыши. Albion Lab прочитает текущую зону, назначение и таймер и сразу сохранит переход в граф. Запись закреплена за выбранным сервером до остановки. После перезапуска запись нужно включить снова; сохранённый граф остаётся.</p><p>Слабое распознавание таймера показывается пунктиром и исключается из маршрутов. Ctrl+Shift+A в разделе карт читает только название. Наземные дороги не добавляются автоматически.</p></details>
<div class="roads-controls"><label class="field">Откуда<input id="roads-from" list="avalon-zone-list" placeholder="Текущая зона" maxlength="100"></label><label class="field">Куда<select id="roads-target"><option value="safe">Ближайшая синяя / жёлтая зона или город</option><option value="portal">Отмеченный выход к предпортальному городу</option><option value="exact">Конкретная зона</option></select></label><label class="field">Предпортальный город<select id="roads-destination-city"><option value="">Любой отмеченный</option></select></label><label class="field">Зона назначения<input id="roads-to" list="avalon-zone-list" maxlength="100" placeholder="Если выбрана конкретная зона"></label><label class="field">Поиск<select id="roads-mode"><option value="shortest">Меньше переходов</option><option value="lifetime">Дольше доступен</option></select></label><label class="field">Запас времени, мин<input id="roads-reserve" type="number" min="0" max="1440" value="10"></label></div>
<p id="roads-route" class="roads-route" role="status"></p><label><input id="roads-expired" type="checkbox"> Показать истёкшие связи</label><div id="roads-graph" class="roads-graph"></div><p class="hint">Один клик — начало пути, двойной клик или Enter — содержимое зоны. Подпись линии — до закрытия портала. Золотой — найденный маршрут; пунктир — неизвестное время. Число у узла — связи с другими зонами. Вместимость и заряды порталов не считываются.</p>
<div class="avalon-actions"><label class="field">Для выбранной зоны: выход рядом с<select id="roads-city"></select></label><button class="button" id="roads-details">Что находится в зоне</button><button class="button" id="roads-mark">Отметить выход</button><button class="button" id="roads-unmark">Снять отметку</button></div><p id="roads-count" class="hint"></p><div id="roads-edges" class="roads-edges"></div>`;
$('avalon-content').querySelector('.avalon-heading').after(panel);
let state={edges:[],marks:{},session:null},busy=false,loaded=false,lastKey='',clickTimer=null;
const detail=document.createElement('dialog');detail.id='roads-detail-dialog';detail.className='roads-detail-dialog';detail.setAttribute('aria-labelledby','roads-detail-title');document.body.append(detail);
const zones=()=>window.AvalonUI?.catalog()||[],server=()=>ActivityViews.avalon.state.server,name=id=>zones().find(z=>z.id===id)?.name||id;
function status(text,bad=false){$('roads-status').textContent=text;$('roads-status').classList.toggle('avalon-error',bad);}
const zoneByName=s=>zones().find(z=>AvalonMath.normalize(z.name)===AvalonMath.normalize(s));
const MarkerLabel=kind=>({black:'Чёрная зона',blue:'Синяя зона / город',yellow:'Жёлтая зона',red:'Красная зона',unknown:'Внешняя зона'}[kind]);
function left(expires){if(expires===null)return 'таймер ?';const min=Math.floor((expires-Date.now())/60000);return min<0?'истёк':min<1?'< 1 мин':`${Math.floor(min/60)} ч ${min%60} мин`;}
function edges(){const manual=(AvalonUI.snapshot().saved.timers||[]).map(t=>({...t,captured:t.captured||0,source:'manual'}));return R.merge([...state.edges,...manual].filter(e=>e.server===server()));}
function render(){if(!zones().length||clickTimer||detail.open)return;const all=edges(),now=Date.now(),reserve=Number($('roads-reserve').value),start=zoneByName($('roads-from').value)?.id,target=$('roads-target').value,ids=zones().filter(z=>target==='safe'?R.classify(z)==='safe':target==='portal'?($('roads-destination-city').value?z.id===$('roads-destination-city').value||state.marks[server()+':'+z.id]===$('roads-destination-city').value:R.classify(z)==='portal'||state.marks[server()+':'+z.id]):z.id===zoneByName($('roads-to').value)?.id).map(z=>z.id),validReserve=Number.isInteger(reserve)&&reserve>=0&&reserve<=1440;
 const route=validReserve?R.route(all,start,ids,{now,reserve:reserve*60000,mode:$('roads-mode').value}):null;
 $('roads-to').disabled=target!=='exact';$('roads-destination-city').disabled=target!=='portal';$('roads-route').textContent=!validReserve?'Укажите запас от 0 до 1440 минут.':!start?'Выберите начальную зону.':route?route.hops?`${route.nodes.map(name).join(' → ')} · ${route.hops} переходов · весь путь доступен ещё ${left(route.expires)} (до ${new Date(route.expires).toLocaleTimeString('ru-RU')}). Запас ${reserve} мин вычтен при отборе путей.`:'Вы уже в выбранной зоне назначения.':'По сохранённым порталам с таким запасом времени путь не найден. Исследуйте соседние зоны или уточните таймеры.';
 const session=window.AvalonEngineUI?.snapshot()?.session||state.session,labels={europe:'Европа',west:'Америка',east:'Азия'};$('roads-record').disabled=busy||window.AvalonEngineUI?.snapshot()?.busy||!!session||!B||!window.AvalonEngineUI?.snapshot()?.available;$('roads-stop').disabled=busy||!session;$('roads-count').textContent=`${all.length} соединений на сервере «${labels[server()]}». ${session?`Запись: ${labels[session.server]} · сохранено ${session.count}${session.server!==server()?' · выбран другой сервер, запись остаётся на прежнем':''}`:'Запись выключена.'}`;
 const visible=all.filter(e=>$('roads-expired').checked||e.expires===null||e.expires>now),routeKeys=new Set((route?.edges||[]).map(e=>R.key(e.from,e.to)));
 const adjacency=new Map();for(const e of visible)for(const [a,b]of [[e.from,e.to],[e.to,e.from]]){if(!adjacency.has(a))adjacency.set(a,[]);adjacency.get(a).push(b);}const ordered=[],depth=new Map(),roots=[...(start?[start]:[]),...adjacency.keys()];
 for(const root of roots){if(depth.has(root)||!adjacency.has(root))continue;depth.set(root,0);const queue=[root];while(queue.length){const a=queue.shift();ordered.push(a);for(const b of adjacency.get(a)||[])if(!depth.has(b)){depth.set(b,depth.get(a)+1);queue.push(b);}}}
 const idsVisible=ordered.slice(0,120),cols=new Map(),position=new Map();for(const id of idsVisible){const column=Math.min(depth.get(id)||0,7);if(!cols.has(column))cols.set(column,[]);cols.get(column).push(id);}let height=200;for(const [column,nodes]of cols){height=Math.max(height,nodes.length*90+60);nodes.forEach((id,i)=>position.set(id,{x:110+column*300,y:55+i*90}));}const width=Math.max(600,...[...cols.keys()].map(n=>n*300+320));
 if(!visible.length)$('roads-graph').innerHTML='<p class="hint">Граф пока пуст. Считайте порталы в Checker во время записи или добавьте найденное соединение в «Мои порталы» ниже.</p>';
 else $('roads-graph').innerHTML=`<svg viewBox="0 0 ${width} ${height}" style="min-width:${Math.min(width,1800)}px;height:${height}px" role="img" aria-label="Граф наблюдаемых переходов">${visible.filter(e=>position.has(e.from)&&position.has(e.to)).map(e=>{const a=position.get(e.from),b=position.get(e.to),highlight=routeKeys.has(R.key(e.from,e.to)),geometry=R.edgeGeometry(a,b);return `<g class="roads-link ${highlight?'route':''} ${e.expires===null?'unknown':''} ${e.expires!==null&&e.expires<=now?'expired':''}"><title>${esc(name(e.from))} ↔ ${esc(name(e.to))}: ${esc(left(e.expires))}</title><path d="${geometry.path}" fill="none"/><text x="${geometry.labelX}" y="${geometry.labelY}">${esc(left(e.expires))}</text></g>`;}).join('')}${idsVisible.map(id=>{const p=position.get(id),z=zones().find(z=>z.id===id),mark=state.marks[server()+':'+id],badge=R.exitBadge(z),labelX=p.x+(badge?23:0);return `<g class="roads-node ${R.classify(z)} ${id===start?'selected':''}" data-roads-node="${esc(id)}" data-roads-tier="${z?.tier||0}" style="--roads-tier:${R.tierColor(z?.tier)}" data-roads-degree="${adjacency.get(id)?.length||0}" role="button" tabindex="0" aria-label="${esc(name(id))}: Enter — содержимое зоны; пробел — начало пути"><title>${esc(name(id))}${mark?' · отмечен выход к '+esc(name(mark)):''}</title><rect class="roads-node-frame" x="${p.x-93}" y="${p.y-25}" width="186" height="50" rx="10"/>${badge?`<g class="roads-exit-badge" data-exit-color="${badge.kind}" style="--exit-fill:${badge.fill};--exit-ink:${badge.ink}"><title>${esc(MarkerLabel(badge.kind))} · ${esc(badge.label)}</title><rect x="${p.x-87}" y="${p.y-18}" width="36" height="36" rx="2"/><text x="${p.x-69}" y="${p.y+4}">${esc(badge.label)}</text></g>`:''}<text x="${labelX}" y="${p.y-2}">${esc(name(id).length>(badge?19:24)?name(id).slice(0,badge?18:23)+'…':name(id))}</text><text class="roads-node-meta" x="${labelX}" y="${p.y+15}">${mark?'↗ '+esc(name(mark)):esc(AvalonMath.worlds[z?.world]||'Зона')}</text><circle class="roads-degree-dot" cx="${p.x+88}" cy="${p.y-23}" r="11"/><text class="roads-degree" x="${p.x+88}" y="${p.y-19}">${adjacency.get(id)?.length||0}</text></g>`;}).join('')}</svg>`;
 $('roads-edges').innerHTML=(idsVisible.length<ordered.length?'<p class="hint">На рисунке первые 120 зон, список и расчёт используют весь граф. Выберите начало пути, чтобы увидеть его окружение.</p>':'')+visible.slice(0,250).map(e=>`<div class="avalon-timer"><span>${esc(name(e.from))} ↔ ${esc(name(e.to))}<small>${e.source==='engine'?'Встроенный сканер':e.source==='checker'?'Старый скан Checker':'Вручную'} · ${e.captured?new Date(e.captured).toLocaleTimeString('ru-RU'):'время добавления неизвестно'}</small></span><b>${esc(left(e.expires))}</b><button class="button" data-roads-edit="${esc(e.id)}">Уточнить таймер</button><button class="button" data-roads-remove="${esc(e.id)}">Удалить</button></div>`).join('')+(visible.length>250?'<p class="hint">В списке первые 250 связей.</p>':'');
}
async function refresh(){if(!B||busy)return;try{state=await B.roads('state');if(state.error)status(state.error,true);render();}catch(e){status(e.message,true);}}
async function engine(){await window.AvalonEngineUI?.refresh();}
async function action(fn){if(busy)return;busy=true;panel.querySelectorAll('button').forEach(b=>b.disabled=true);try{await fn();status('Готово.');}catch(e){status(e.message,true);}finally{busy=false;panel.querySelectorAll('button').forEach(b=>b.disabled=false);await refresh();}}
for(const id of ['roads-from','roads-target','roads-destination-city','roads-to','roads-mode','roads-reserve','roads-expired'])$(id).addEventListener(id.includes('from')||id==='roads-to'||id==='roads-reserve'?'input':'change',render);
function selectNode(target){const button=target.closest('[data-roads-node]');if(button){$('roads-from').value=name(button.dataset.roadsNode);render();}}
function showDetail(id){const z=zones().find(z=>z.id===id);if(!z){status('Выберите зону начала пути или дважды нажмите узел графа.',true);return;}clearTimeout(clickTimer);clickTimer=null;const note=AvalonUI.snapshot().saved.notes[id];detail.innerHTML=`<div class="avalon-zone-heading"><div><h2 id="roads-detail-title">${esc(z.name)}</h2><p class="hint">T${AvalonMath.zoneLabel(z)} · ${esc(AvalonMath.worlds[z.world])}</p></div><button class="button" id="roads-detail-close" aria-label="Закрыть сведения о зоне">Закрыть</button></div><p class="hint">Содержимое по справочнику Checker. Наличие, зачистка плит/сундуков и текущий запас ресурсов не считываются.</p><div class="roads-detail-features avalon-features">${AvalonUI.features(z).replace('<h3>Сундуки</h3>','<h3>Плиты и сундуки</h3>')}</div>${note?`<p class="roads-detail-note"><b>Моя заметка:</b> ${esc(note)}</p>`:''}<div class="avalon-map">${z.image?`<img src="avalon-local/${encodeURIComponent(z.image)}" alt="Карта ${esc(z.name)}">`:'<p class="hint">Для этой зоны нет изображения в справочнике.</p>'}</div><div class="avalon-actions"><button class="button" id="roads-detail-start">Начать маршрут отсюда</button><button class="button" id="roads-detail-map" ${z.image&&B?'':'disabled'}>Карта поверх игры</button></div>`;detail.querySelector('#roads-detail-close').onclick=()=>detail.close();detail.querySelector('#roads-detail-start').onclick=()=>{$('roads-from').value=z.name;detail.close();render();};detail.querySelector('#roads-detail-map').onclick=async()=>{try{await B.overlay(z.id);}catch(e){status(e.message,true);}};if(!detail.open)detail.showModal();}
$('roads-graph').onclick=e=>{const node=e.target.closest('[data-roads-node]');if(!node)return;const id=node.dataset.roadsNode;clearTimeout(clickTimer);clickTimer=setTimeout(()=>{clickTimer=null;$('roads-from').value=name(id);render();},550);};
$('roads-graph').ondblclick=e=>{const node=e.target.closest('[data-roads-node]');if(node){e.preventDefault();showDetail(node.dataset.roadsNode);}};
$('roads-graph').onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();const node=e.target.closest('[data-roads-node]');if(node)showDetail(node.dataset.roadsNode);}else if(e.key===' '){e.preventDefault();selectNode(e.target);}};
$('roads-details').onclick=()=>showDetail(zoneByName($('roads-from').value)?.id);detail.addEventListener('close',()=>{render();$('roads-details').focus({preventScroll:true});});
$('roads-mark').onclick=()=>action(async()=>{const z=zoneByName($('roads-from').value);if(!z)throw Error('Сначала выберите начальную зону.');await B.roads('mark',{server:server(),id:z.id,city:$('roads-city').value});});$('roads-unmark').onclick=()=>action(async()=>{const z=zoneByName($('roads-from').value);if(!z)throw Error('Выберите зону.');await B.roads('mark',{server:server(),id:z.id,city:''});});
$('roads-edges').onclick=e=>{const remove=e.target.closest('[data-roads-remove]'),edit=e.target.closest('[data-roads-edit]'),edge=edges().find(x=>x.id===(remove?.dataset.roadsRemove||edit?.dataset.roadsEdit));if(!edge)return;if(edit){AvalonUI.select(edge.from);$('avalon-to').value=name(edge.to);$('avalon-minutes').focus();$('avalon-minutes').scrollIntoView({block:'center'});status('Введите оставшееся время из игры и нажмите «Добавить портал» в форме ниже.');}else action(async()=>{const automatic=state.edges.find(e=>e.server===server()&&R.key(e.from,e.to)===R.key(edge.from,edge.to));if(automatic)await B.roads('remove',{id:automatic.id});AvalonUI.removeConnection(server(),edge.from,edge.to);});};
setInterval(()=>{if(!ActivityViews.avalon.active())return;const key=zones().length+':'+server();if(key!==lastKey){lastKey=key;$('roads-city').innerHTML=zones().filter(z=>R.classify(z)==='portal').map(z=>`<option value="${esc(z.id)}">${esc(z.name)}</option>`).join('');$('roads-destination-city').innerHTML='<option value="">Любой отмеченный</option>'+$('roads-city').innerHTML;if(!loaded){loaded=true;engine();}}refresh();},2000);
B?.onRoads(refresh);window.AvalonRoadsUI={refresh,render,snapshot:()=>state};
})();
